mapper.select:
SELECT

FROM
iot_device_property
WHERE
del_flag = '0'

    AND device_id = #{property.deviceId}


    AND device_code = #{property.deviceCode}


    AND product_id = #{property.productId}


    AND identifier = #{property.identifier}


    AND name LIKE CONCAT('%', #{property.name}, '%')


    AND factory_code = #{property.factoryCode}

ORDER BY collect_time DESC

SELECT p.*
FROM iot_device_property p JOIN iot_device d ON p.device_id=d.id
  AND d.tenant_id=p.tenant_id AND d.factory_code=p.factory_code
WHERE p.del_flag='0' AND d.del_flag='0' AND p.scope_verified=true
  AND p.tenant_id=#{tenantId} AND p.factory_code=#{factory}
  AND p.product_id=#{productId} AND d.product_id=#{productId}

    AND p.device_id IN
    #{deviceId}

AND p.identifier=#{identifier}
AND p.collect_time >= CAST(#{startTime} AS timestamp) AND p.collect_time < CAST(#{endTime} AS timestamp)
ORDER BY p.collect_time DESC,p.id DESC

SELECT p.*, d.device_code, d.device_name
FROM iot_device_property p
LEFT JOIN iot_device d ON p.device_id = d.id
WHERE d.product_id = #{productId}

    AND p.identifier = #{identifier}


    AND p.create_time >= #{startTime}


    AND p.create_time <= #{endTime}

ORDER BY p.create_time DESC
